import type { IconBaseProps, IconType } from "react-icons";
import { PublicIcon } from "./PublicIcon";

type DashboardPublicIconProps = IconBaseProps;

const DashboardPublicIcon = ({
  src,
  label,
  size = 18,
  className,
}: DashboardPublicIconProps & { src: string; label: string }) => {
  return <PublicIcon src={src} label={label} size={size} className={className} decorative />;
};

export const DashboardGaugeIcon: IconType = (props) => {
  return <DashboardPublicIcon {...props} src="/icons/gauge-svgrepo-com.svg" label="Tableau de bord" />;
};

export const DashboardHomeIcon: IconType = ({ size = 18, className, ...props }) => {
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      width={size}
      height={size}
      viewBox="0 0 24 24"
      fill="none"
      stroke="currentColor"
      strokeWidth="2"
      strokeLinecap="round"
      strokeLinejoin="round"
      className={className}
      aria-hidden="true"
      {...props}
    >
      <path d="M15 21v-8a1 1 0 0 0-1-1h-4a1 1 0 0 0-1 1v8" />
      <path d="M3 10a2 2 0 0 1 .709-1.528l7-5.999a2 2 0 0 1 2.582 0l7 5.999A2 2 0 0 1 21 10v9a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z" />
    </svg>
  );
};

